// 패치노트 생성 — git log를 파싱해 public/changelog.json으로. 빌드/CI에서 실행(.git 있을 때).
//   git이 없으면(슬림 Docker 빌드 등) ★기존 파일 유지★(graceful) — 커밋된 스냅샷이 폴백.
import { execSync } from "node:child_process";
import { writeFileSync, existsSync } from "node:fs";
import { mkdirSync } from "node:fs";

const OUT = "public/changelog.json";
const MAX = 80; // 최근 N개

// conventional-commit 접두 → 한글 라벨·이모지. 그 외는 '기타'.
const TYPES = {
  feat: { label: "기능", emoji: "✨" },
  fix: { label: "수정", emoji: "🐛" },
  perf: { label: "성능", emoji: "⚡" },
  ux: { label: "사용성", emoji: "🎨" },
  refactor: { label: "정리", emoji: "♻️" },
  docs: { label: "문서", emoji: "📝" },
  chore: { label: "관리", emoji: "🔧" },
  ci: { label: "배포", emoji: "🚀" },
  ops: { label: "운영", emoji: "🛠" },
  test: { label: "테스트", emoji: "✅" },
};

function parseSubject(s) {
  // "feat: 제목" / "fix(ci): 제목" / "ci: 제목" → {type, title}
  const m = s.match(/^(\w+)(?:\([^)]*\))?:\s*(.+)$/);
  if (m && TYPES[m[1]]) return { type: m[1], title: m[2].trim() };
  if (m) return { type: "기타", title: m[2].trim() };
  return { type: "기타", title: s.trim() };
}

let raw = "";
try {
  // %x1f=필드구분, %x1e=레코드구분. 본문(%b)에서 Co-Authored-By 등 트레일러는 제외.
  raw = execSync(`git log -n ${MAX} --no-merges --pretty=format:%H%x1f%aI%x1f%s%x1f%b%x1e`, { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"], maxBuffer: 8 * 1024 * 1024 });
} catch {
  if (existsSync(OUT)) { console.log("git 없음 — 기존 changelog.json 유지"); process.exit(0); }
  console.log("git 없음 + 기존 파일 없음 — 빈 changelog 생성");
}

const entries = raw.split("\x1e").map((rec) => rec.trim()).filter(Boolean).map((rec) => {
  const [hash, dateISO, subject, body = ""] = rec.split("\x1f");
  const { type, title } = parseSubject(subject || "");
  // 본문에서 트레일러(Co-Authored-By, Generated)·빈 줄 정리.
  const cleanBody = body.split("\n").filter((l) => !/^(Co-Authored-By|🤖 Generated|Signed-off-by)/i.test(l.trim())).join("\n").trim();
  return { hash: (hash || "").slice(0, 40), short: (hash || "").slice(0, 7), date: (dateISO || "").slice(0, 10), type, title, body: cleanBody };
}).filter((e) => e.title);

try { mkdirSync("public", { recursive: true }); } catch { /* */ }
writeFileSync(OUT, JSON.stringify({ generatedAt: entries[0]?.date || "", count: entries.length, entries }, null, 0), "utf8");
console.log(`changelog.json 생성: ${entries.length}개 (최근 ${entries[0]?.date} ~ ${entries[entries.length - 1]?.date})`);

