1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth/session";
3	import { assertScopeAllowed, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
4	import { prisma } from "@/lib/db";
5	import { storeForAnalysis, storeRawOnly } from "@/lib/ingest";
6	import { extractAsset, SUPPORTED_EXTS, STT_EXTS } from "@/lib/extract";
7	import { STT_FFMPEG_EXTS, sttAvailable, isTranscribedExtractor } from "@/lib/stt";
8	import { CONVERT_ONLY_EXTS, libreOfficeAvailable, ffmpegAvailable } from "@/lib/convert";
9	import { currentUploadPolicy, uploadPolicyForModel, uploadPoliciesForModels } from "@/lib/uploadPolicy";
10	import { listSelectableModels, resolveIngestModel, ingestModelChoice, recommendIngestModel, pickIngestModel } from "@/lib/models";
11	import { disabledModelIds, enabledModelIds } from "@/lib/modelSettings";
12	import { modelFor } from "@/lib/anthropic";
13	import { avatarForUser } from "@/lib/avatar";
14	
15	// 자료 업로드(텍스트/MD) → 인제스트 → 위키. ACL 강제지점3(인제스트 적용). docs/06·docs/07 §2.
16	export const runtime = "nodejs";
17	export const maxDuration = 600; // 무거운 자료를 추론 모델(claude/codex)이 분석할 때 길어질 수 있음(타임아웃 600초와 정렬)
18	
19	// GET: scope의 최근 자료 목록
20	export async function GET(req: Request) {
21	  const user = await getSessionUser();
22	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
23	  const scope = new URL(req.url).searchParams.get("scope") ?? "";
24	  try {
25	    await assertScopeAllowed(user, scope);
26	  } catch {
27	    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
28	  }
29	  const wikiScope = scopeWikiPrefix(scope);
30	  // 기본은 활성(archivedAt=null)만. ?archived=1 → 아카이브된 자료(복원/영구삭제 뷰).
31	  const showArchived = new URL(req.url).searchParams.get("archived") === "1";
32	  const sources = await prisma.source.findMany({
33	    where: { teamScope: wikiScope, archivedAt: showArchived ? { not: null } : null },
34	    orderBy: { id: "desc" },
35	    take: 30,
36	    include: { ingestJobs: { orderBy: { id: "desc" }, take: 1 } },
37	  });
38	  const queryModels = await listSelectableModels(); // ★결제 전 API Claude 숨김★(드롭다운용)
39	  const canManage = await canManageScope(user, wikiScope); // 아카이브·영구삭제 권한(룸 관리자)
40	  // 소스별 '자동선택 모델'(recoModel)을 동봉 — 셋·기본값을 ★1회만★ 조회하고 동기 코어로 소스마다 계산.
41	  const [disabled, explicitOn, fallback] = await Promise.all([disabledModelIds(), enabledModelIds(), ingestModelChoice()]);
42	  // 업로더 표시 — id→이름·아바타. ★익명이어도 관리자/룸관리자는 실명 확인★(감사기록 유지), 동료에겐 '익명 기여자'.
43	  const uploaderIds = [...new Set(sources.map((s) => s.uploadedBy).filter((x): x is number => x != null))];
44	  const uploaders = uploaderIds.length
45	    ? await prisma.user.findMany({ where: { id: { in: uploaderIds } }, select: { id: true, name: true, email: true, avatarColor: true, avatarMime: true } })
46	    : [];
47	  const userById = new Map(uploaders.map((u) => [u.id, u]));
48	  const canReveal = canManage || user.role === "ADMIN";
49	  return NextResponse.json({
50	    canManage,
51	    sources: sources.map((s) => {
52	      let prov: { hasText?: boolean; looksOrganized?: boolean } = {};
53	      try { prov = JSON.parse(s.provenance || "{}"); } catch { /* */ }
54	      const transcribed = isTranscribedExtractor(s.extractor); // 전사 소스 = byteSize 휴리스틱 제외 + Groq 분석 기본
55	      return {
56	        id: s.id,
57	        title: s.title,
58	        type: s.type,
59	        createdAt: s.createdAt.toISOString(),
60	        archived: Boolean(s.archivedAt),
61	        // 잡이 있으면 그 상태, 미분석 보존(UNANALYZED)이면 그대로, 그 외 잡 없는 신규 소스 = '분석 대기'(PENDING).
62	        status: s.ingestJobs[0]?.status ?? (s.extractStatus === "UNANALYZED" ? "UNANALYZED" : "PENDING"),
63	        confidence: s.ingestJobs[0]?.confidence ?? null,
64	        gate: s.ingestJobs[0]?.gate ?? null,
65	        error: s.ingestJobs[0]?.error ?? null, // 실패(FAILED) 사유 전문 — UI에서 표시·복사
66	        model: s.ingestJobs[0]?.model ?? null, // 분석에 쓰인 모델(실패 진단 참고)
67	        phase: s.ingestJobs[0]?.phase ?? null, // L2 비동기 처리 단계(대기 중/분석…) — QUEUED/RUNNING 배지 보조
68	        progress: s.ingestJobs[0]?.progress ?? null, // L2 진행률(0~100), null=동기/미사용
69	        byteSize: s.byteSize ?? null, // 원본 파일 용량(업로드 바이트). 전사 소스는 오디오 바이트=원본 용량.
70	        // [AI로 분석]/[다시 분석]이 ★자동★(모델 미선택)일 때 서버가 고를 모델 — '처리 중 {모델}' 배지를 정확히.
71	        // ★전사 소스(groq-/gemini-)는 byteSize=오디오 바이트라 텍스트 길이 아님 → 크기 휴리스틱 제외 + Groq 분석 기본.
72	        recoModel: pickIngestModel({ type: s.type, chars: transcribed ? undefined : (s.byteSize ?? undefined), transcribed }, { disabled, explicitOn, fallback }).model,
73	        extractStatus: s.extractStatus ?? null,
74	        extractor: s.extractor ?? null,
75	        hasExtracted: Boolean(s.normalizedPath),
76	        hasText: Boolean(prov.hasText ?? s.normalizedPath), // '원본 그대로' 가능 여부
77	        looksOrganized: Boolean(prov.looksOrganized), // 이미 위키 형식 → '원본 그대로' 추천
78	        anonymous: s.anonymous, // 동료 표시용 익명 여부
79	        // 업로더 표시: 익명+비관리자면 숨김(null→UI '익명 기여자'). 관리자/룸관리자는 익명이어도 실명+아바타.
80	        uploader: (() => {
81	          const up = s.uploadedBy != null ? userById.get(s.uploadedBy) : null;
82	          if (!up || (s.anonymous && !canReveal)) return null; // 동료엔 익명 → null
83	          return { name: up.name || up.email, avatar: avatarForUser(up) }; // {name, avatar:{initials,color,imageUrl}}
84	        })(),
85	      };
86	    }),
87	    // LibreOffice 변환 사이드카(4j)가 켜진 환경에서만 추가 수락되는 포맷 — UI 안내·accept 확장용
88	    convertExts: libreOfficeAvailable() ? CONVERT_ONLY_EXTS : [],
89	    // 업로드 정책(기본 공급자 기준 허용 포맷·안내) — 모델 미선택 시 폴백
90	    policy: currentUploadPolicy(),
91	    // 자료 탭 모델 선택기용: 선택 가능 모델 + ★모델 id별★ 업로드 정책(선택 시 즉시 전환) + 기본 모델
92	    models: queryModels,
93	    policies: uploadPoliciesForModels(queryModels),
94	    defaultModel: modelFor("ingest"),
95	    // [AI로 분석]이 자동으로 쓸 모델 + 사유(툴팁). 사용자는 모델을 고르지 않는다.
96	    analyzeModel: fallback,
97	  });
98	}
99	
100	// POST: 텍스트/MD(JSON) 또는 이미지(multipart) 1건 인제스트
101	export async function POST(req: Request) {
102	  const user = await getSessionUser();
103	  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
104	
105	  // 업로드는 ★스테이징(추출·보관만, 토큰 0)★ — LLM/비용은 [분석] 버튼 시점에. (예산 체크는 analyze 라우트.)
106	  const ct = req.headers.get("content-type") || "";
107	
108	  // 파일 업로드(multipart): 추출 레이어(docs/17)로 정규화 → 인제스트.
109	  // 원본 바이트는 raw로 보존(열람용), 텍스트는 파서로 추출(우선), 안 되면 네이티브 모달리티 폴백.
110	  if (ct.includes("multipart/form-data")) {
111	    const form = await req.formData();
112	    const scope = String(form.get("scope") || "");
113	    const titleField = String(form.get("title") || "");
114	    const anonymous = String(form.get("anonymous") || "") === "true"; // 익명 업로드(표시만 숨김, uploadedBy는 유지)
115	    const diarize = String(form.get("diarize") || "") === "true"; // 음성·영상 화자 구분(Gemini 전용·외부학습) — STT에만 영향
116	    const file = form.get("file");
117	    if (!(file instanceof File)) return NextResponse.json({ error: "파일이 필요합니다." }, { status: 400 });
118	    try {
119	      await assertScopeAllowed(user, scope); // ACL 강제지점3
120	    } catch {
121	      return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
122	    }
123	    // 사용자가 자료 탭에서 고른 인제스트 모델(검증·폴백) → ★그 모델★ 능력 기준으로 게이팅·인제스트.
124	    const picked = await resolveIngestModel(String(form.get("model") || "") || undefined);
125	    const ext = (file.name.toLowerCase().match(/\.([a-z0-9]+)$/)?.[1]) || "";
126	    const pol = uploadPolicyForModel(picked.model, picked.provider);
127	    const isImg = ["image/png", "image/jpeg", "image/gif", "image/webp"].includes(file.type) || ["png", "jpg", "jpeg", "gif", "webp"].includes(ext);
128	    const isPdf = file.type === "application/pdf" || ext === "pdf";
129	    const isConvertible = libreOfficeAvailable() && CONVERT_ONLY_EXTS.includes(ext);
130	    // 게이팅(서버 강제): ① 형식 자체 미지원이면 400, ② 형식은 지원하나 선택 모델로는 불가면 415.
131	    //   음성·영상(STT)은 SUPPORTED_EXTS엔 없고 키 있을 때만 허용 → 여기 1차 게이트에도 포함해야 한다(uploadPolicy와 동일 조건).
132	    const sttExts = sttAvailable() ? [...STT_EXTS, ...(ffmpegAvailable() ? STT_FFMPEG_EXTS : [])] : [];
133	    const allExts = [...SUPPORTED_EXTS, ...(libreOfficeAvailable() ? CONVERT_ONLY_EXTS : []), ...sttExts];
134	    if (!allExts.includes(ext)) {
135	      return NextResponse.json({ error: `지원하지 않는 형식입니다(.${ext || "?"}). 지원: ${allExts.join(", ")}` }, { status: 400 });
136	    }
137	    if (!pol.exts.includes(ext)) {
138	      return NextResponse.json({ error: pol.note }, { status: 415 });
139	    }
140	    // 음성·영상: ★긴 음성 청크 전사(L1)★로 Groq 25MB 한도를 우회하므로 100MB까지 허용(긴 회의 수용, Ingress 128m 내).
141	    //   그 외 문서 50MB. ★더 큰 파일·스트리밍 업로드는 L3(Ingress 512m·비동기 큐) — docs/PLAN-large-files-and-chunking.
142	    const isAudioVideo = file.type.startsWith("audio/") || file.type.startsWith("video/") || STT_EXTS.includes(ext) || STT_FFMPEG_EXTS.includes(ext);
143	    const capMb = isAudioVideo ? 100 : 50;
144	    if (file.size > capMb * 1024 * 1024) {
145	      return NextResponse.json({ error: `파일은 ${capMb}MB 이하만 가능합니다.${isAudioVideo ? " 더 긴 음성·영상은 잘라서 올려주세요." : ""}` }, { status: 400 });
146	    }
147	    const buf = Buffer.from(await file.arrayBuffer());
148	    const wikiScope = scopeWikiPrefix(scope);
149	    const title = titleField.trim() || file.name.replace(/\.[^.]+$/, "") || "자료";
150	    const rawExt = ext || (isPdf ? "pdf" : "bin");
151	    const typeLabel = isPdf ? "PDF" : isImg ? "IMAGE" : (ext ? ext.toUpperCase() : "FILE");
152	
153	    const meta = { mimeType: file.type || undefined, byteSize: buf.byteLength, originalName: file.name };
154	    try {
